  final ValueNotifier<List<AudioTrack>> queueNotifier = ValueNotifier(const []);

  PlayIntent _userIntent = PlayIntent.pause;
  PlayIntent get userIntent => _userIntent;

  ValueNotifier<int?> get currentIndexNotifier =>
